const root = $input.first().json;
const event = root.body ?? root;
const p = event.payload ?? {};
const allowed = new Set(['case.created', 'case.updated', 'followup.due', 'followup.assigned']);
if (!allowed.has(event.event_type)) throw new Error('Unsupported event type');
if (!event.event_id || !event.tenant_id || !event.resource_id) throw new Error('Missing event references');
if (p.contains_student_content !== false) throw new Error('Refusing to send a payload that may contain student content');
if (!p.recipient_email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(p.recipient_email)) {
  throw new Error('No authorized recipient was resolved by the backend; no email sent');
}
if (typeof p.subject !== 'string' || typeof p.message !== 'string') throw new Error('Missing approved notification copy');
if (p.subject.length > 160 || p.message.length > 800) throw new Error('Notification exceeds allowed length');
// Deliberately omit excerpts, student IDs, names, assessment evidence, and message content.
return [{ json: {
  event_id: event.event_id,
  tenant_id: event.tenant_id,
  tenant_slug: String(p.tenant_slug || 'school').slice(0, 80),
  resource_id: String(event.resource_id).slice(0, 64),
  recipient_email: p.recipient_email,
  subject: p.subject,
  message: p.message,
  event_type: event.event_type
} }];
